+/* Highlighted link block at the top of a blog post: repo, website, external references. */
+.prose-lf .post-links {
+  margin: 0 0 1.75rem;
+  padding: .9rem 1.1rem;
+  border: 1px solid #C7D2FE;
+  border-left: 4px solid #6366F1;
+  border-radius: 10px;
+  background: #EEF2FF;
+}
+
+.prose-lf .post-links-row {
+  display: flex;
+  flex-wrap: wrap;
+  gap: .15rem .75rem;
+  padding: .2rem 0;
+  font-size: .95rem;
+}
+
+.prose-lf .post-links-label {
+  flex: none;
+  min-width: 5.5rem;
+  font-weight: 600;
+  color: #374151;
+}
+
+.prose-lf .post-links-row a {
+  min-width: 0;
+  overflow-wrap: anywhere;
+}
+
+/* Wide screens: one shared label column so URLs line up across rows. */
+@media (min-width: 640px) {
+  .prose-lf .post-links {
+    display: grid;
+    grid-template-columns: max-content minmax(0, 1fr);
+    column-gap: .9rem;
+    row-gap: .45rem;
+    align-items: baseline;
+  }
+
+  .prose-lf .post-links-row {
+    display: contents;
+  }
+
+  .prose-lf .post-links-label {
+    min-width: 0;
+  }
+}
+
+.dark .prose-lf .post-links {
+  border-color: #312E81;
+  border-left-color: #818CF8;
+  background: #1E1B4B;
+}
+
+.dark .prose-lf .post-links-label {
+  color: #E5E7EB;
+}
+
+/* Floating "back to top" button, injected by main.js on every page. */
+.back-to-top {
+  position: fixed;
+  right: 1.25rem;
+  bottom: 1.25rem;
+  z-index: 40;
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  width: 2.75rem;
+  height: 2.75rem;
+  border: 1px solid #C7D2FE;
+  border-radius: 9999px;
+  background: #fff;
+  color: #4F46E5;
+  box-shadow: 0 4px 14px rgba(79, 70, 229, .18);
+  cursor: pointer;
+  opacity: 0;
+  visibility: hidden;
+  transform: translateY(8px);
+  transition: opacity .2s ease, transform .2s ease, visibility .2s, background .15s ease;
+}
+
+.back-to-top.visible {
+  opacity: 1;
+  visibility: visible;
+  transform: none;
+}
+
+.back-to-top:hover {
+  background: #EEF2FF;
+}
+
+.back-to-top:focus-visible {
+  outline: 2px solid #6366F1;
+  outline-offset: 2px;
+}
+
+.back-to-top svg {
+  width: 1.25rem;
+  height: 1.25rem;
+}
+
+.dark .back-to-top {
+  border-color: #312E81;
+  background: #111827;
+  color: #A5B4FC;
+  box-shadow: 0 4px 14px rgba(0, 0, 0, .45);
+}
+
+.dark .back-to-top:hover {
+  background: #1E1B4B;
+}
+
+@media (prefers-reduced-motion: reduce) {
+  .back-to-top {
+    transition: none;
+  }
+}
